#include <array>
#include <vector>
#include <random>
#include <chrono>
#include <iostream>
#include <algorithm>
#include <csignal>
using namespace std;
using Word=unsigned long long;
constexpr int V=14,MAX=64;
struct Gate{int op,a,b;};
using Circuit=vector<Gate>;
using Values=array<Word,MAX>;
mt19937 rng;
volatile sig_atomic_t stopFlag=0;
void stopped(int){stopFlag=1;}
array<Word,V>inputs;
Word target=0;
vector<pair<int,int>>edges;
vector<int>rows;
int N,elastic;
array<bool,MAX> cone(const Circuit&c){array<bool,MAX>used{};used[V+N-1]=true;for(int i=N-1;i>=0;i--)if(used[V+i]){used[c[i].a]=true;used[c[i].b]=true;}return used;}
int cost(const Circuit&c){auto used=cone(c);int n=0;for(int i=0;i<N;i++)n+=used[V+i];return n;}
int deficiency(const Circuit&c){array<unsigned,MAX> singles{},pairs{};for(int v=0;v<V;v++)singles[v]=1u<<v;for(int i=0;i<N;i++){auto g=c[i];if(g.op){singles[V+i]=singles[g.a]|singles[g.b];pairs[V+i]=pairs[g.a]|pairs[g.b];}else{for(size_t e=0;e<edges.size();e++){auto[a,b]=edges[e];if(((singles[g.a]>>a&1)&&(singles[g.b]>>b&1))||((singles[g.a]>>b&1)&&(singles[g.b]>>a&1)))pairs[V+i]|=1u<<e;}}}return edges.size()-__builtin_popcount(pairs[V+N-1]);}
int objective(const Circuit&c){return 32*cost(c)-deficiency(c);}
Values values(const Circuit&c){Values w{};for(int i=0;i<V;i++)w[i]=inputs[i];for(int i=0;i<N;i++){auto g=c[i];w[V+i]=g.op?(w[g.a]|w[g.b]):(w[g.a]&w[g.b]);}return w;}
void collapse(Circuit&c){auto w=values(c);array<int,MAX>rep{};for(int v=0;v<V;v++)rep[v]=v;for(int i=0;i<N;i++){c[i].a=rep[c[i].a];c[i].b=rep[c[i].b];rep[V+i]=V+i;for(int j=0;j<V+i;j++)if(w[j]==w[V+i]){rep[V+i]=rep[j];break;}}int output=rep[V+N-1];if(output<V){cerr<<"FAULT primary target"<<endl;exit(2);}if(output!=V+N-1)c[N-1]=c[output-V];}
int error(Word value){Word bad=value^target;return __builtin_popcountll(bad)+(elastic?0:3*__builtin_popcountll(bad&~target));}
int score(const Circuit&c){auto w=values(c);int e=error(w[V+N-1]);return elastic?e*8192+objective(c):e;}
Word forceOutput(const Circuit&c,Values w,int i,Word v){w[V+i]=v;for(int j=i+1;j<N;j++){auto g=c[j];w[V+j]=g.op?(w[g.a]|w[g.b]):(w[g.a]&w[g.b]);}return w[V+N-1];}
int coordinate(Circuit&c,int i,int temp){auto live=cone(c);if(!live[V+i]){c[i]={int(rng()%2),int(rng()%(V+i)),int(rng()%(V+i))};return score(c);}auto w=values(c);Word f0=forceOutput(c,w,i,0),f1=forceOutput(c,w,i,~0ULL),care=f0^f1,want=target^f0;int best=100000,count=0;Gate keep=c[i];
 for(int op=0;op<2;op++)for(int a=0;a<V+i;a++)for(int b=0;b<=a;b++){Word value=op?(w[a]|w[b]):(w[a]&w[b]);Word bad=(value^want)&care;int err=__builtin_popcountll(bad)+(elastic?0:3*__builtin_popcountll(bad&~target));Gate old=c[i];c[i]={op,a,b};int sc=elastic?err*8192+objective(c):err;c[i]=old;if(temp)sc+=rng()%(temp+1);if(sc<best){best=sc;count=1;keep={op,a,b};}else if(sc==best&&rng()%++count==0)keep={op,a,b};}c[i]=keep;return score(c);}
int resubstitute(Circuit&c){auto live=cone(c);vector<pair<int,int>>pairs;for(int j=0;j<N-1;j++)if(!live[V+j])for(int i=j+1;i<N;i++)if(live[V+i])pairs.push_back({j,i});if(pairs.empty())return score(c);auto[j,i]=pairs[rng()%pairs.size()];auto w=values(c);Word f0=forceOutput(c,w,i,0),f1=forceOutput(c,w,i,~0ULL),care=f0^f1,want=target^f0;int best=elastic?objective(c):100000,count=elastic?1:0;Gate keepJ=c[j],keepI=c[i];
 for(int op=0;op<2;op++)for(int a=0;a<V+j;a++)for(int b=0;b<=a;b++){Word h=op?(w[a]|w[b]):(w[a]&w[b]);for(int op2=0;op2<2;op2++)for(int d=0;d<V+j;d++){Word value=op2?(h|w[d]):(h&w[d]);Word bad=(value^want)&care;if(elastic&&bad)continue;int err=__builtin_popcountll(bad)+(elastic?0:3*__builtin_popcountll(bad&~target));c[j]={op,a,b};c[i]={op2,V+j,d};int sc=elastic?objective(c):err+int(rng()%4);if(sc<best){best=sc;count=1;keepJ=c[j];keepI=c[i];}else if(sc==best&&rng()%++count==0){keepJ=c[j];keepI=c[i];}}}c[j]=keepJ;c[i]=keepI;return score(c);}
int pivotalStars(Circuit&c){int best=score(c);for(int i=0;i<N;i++){auto live=cone(c);if(!live[V+i])continue;auto w=values(c);Word pivotal=target&~forceOutput(c,w,i,0);if(!pivotal)continue;for(int center=0;center<V;center++){vector<int>leaves;bool star=true;for(size_t e=0;e<edges.size();e++)if(pivotal>>e&1){auto[a,b]=edges[e];if(a!=center&&b!=center){star=false;break;}leaves.push_back(a==center?b:a);}if(!star||leaves.empty()||leaves.size()>3)continue;vector<int>dead;for(int j=0;j<i;j++)if(!live[V+j])dead.push_back(j);if(dead.size()+1<leaves.size())continue;Circuit d=c;int cur=leaves[0];for(size_t k=1;k<leaves.size();k++){int j=dead[k-1];d[j]={1,cur,leaves[k]};cur=V+j;}d[i]={0,center,cur};collapse(d);int sc=score(d);if(sc>=8192){cerr<<"FAULT pivotal replacement"<<endl;exit(2);}if(sc<best||(sc==best&&rng()%2)){c=d;best=sc;}}}return best;}
Circuit seed(){array<vector<int>,V>star;int side=rng()%2,lost=elastic?-1:int(rng()%edges.size()),ei=0;for(auto[a,b]:edges){if(ei++==lost)continue;if(side)swap(a,b);star[a].push_back(b);}vector<int>centers;for(int i=0;i<V;i++)if(!star[i].empty())centers.push_back(i);shuffle(centers.begin(),centers.end(),rng);Circuit c;vector<int>roots;for(int v:centers){shuffle(star[v].begin(),star[v].end(),rng);int cur=star[v][0];for(size_t j=1;j<star[v].size();j++){c.push_back({1,cur,star[v][j]});cur=V+c.size()-1;}c.push_back({0,v,cur});roots.push_back(V+c.size()-1);}while(roots.size()>1){shuffle(roots.begin(),roots.end(),rng);int a=roots.back();roots.pop_back();int b=roots.back();roots.pop_back();c.push_back({1,a,b});roots.push_back(V+c.size()-1);}while(int(c.size())<N){int pos=rng()%c.size();for(size_t j=pos;j<c.size();j++)for(int*p:{&c[j].a,&c[j].b})if(*p>=V+pos)++*p;c.insert(c.begin()+pos,{int(rng()%2),int(rng()%(V+pos)),int(rng()%(V+pos))});}if(int(c.size())!=N){cerr<<"FAULT seed size "<<c.size()<<endl;exit(2);}return c;}
void reorder(Circuit&c){int i=rng()%(N-2);auto g=c[i+1];if(g.a==V+i||g.b==V+i)return;swap(c[i],c[i+1]);for(int j=i+2;j<N;j++)for(int*p:{&c[j].a,&c[j].b}){if(*p==V+i)++*p;else if(*p==V+i+1)--*p;}}
void show(const Circuit&c,int s,long long trial){cout<<"best "<<s<<" trial "<<trial<<" gates [";for(auto g:c)cout<<"("<<g.op<<","<<g.a<<","<<g.b<<"),";cout<<"]"<<endl;}
void witness(const Circuit&c){for(int x=0;x<(1<<V);x++){array<bool,MAX>w{};for(int v=0;v<V;v++)w[v]=x>>v&1;for(int i=0;i<N;i++){auto g=c[i];if(g.op<0||g.op>1||g.a<0||g.b<0||g.a>=V+i||g.b>=V+i){cerr<<"FAULT witness indices"<<endl;exit(2);}w[V+i]=g.op?(w[g.a]||w[g.b]):(w[g.a]&&w[g.b]);}bool wanted=false;for(auto[a,b]:edges)wanted|=(x>>a&1)&&(x>>b&1);if(w[V+N-1]!=wanted){cerr<<"FAULT full truth table"<<endl;exit(2);}}auto live=cone(c);array<int,MAX>map;map.fill(-1);for(int i=0;i<V;i++)map[i]=i;Circuit out;for(int i=0;i<N;i++)if(live[V+i]){auto g=c[i];map[V+i]=V+out.size();out.push_back({g.op,map[g.a],map[g.b]});}cout<<"WITNESS {\"inputs\":14,\"output\":"<<map[V+N-1]<<",\"gates\":[";for(size_t i=0;i<out.size();i++){if(i)cout<<",";auto g=out[i];cout<<"["<<g.op<<","<<g.a<<","<<g.b<<"]";}cout<<"]}"<<endl;}
int main(int argc,char**argv){signal(SIGINT,stopped);signal(SIGTERM,stopped);rng.seed(argc>1?stoul(argv[1]):977501);int secs=argc>2?stoi(argv[2]):1200;elastic=argc>3?stoi(argv[3]):1;N=elastic?29:24;
 edges={{0,8},{0,10},{1,7},{1,9},{1,13},{2,8},{2,13},{3,7},{3,11},{3,12},{4,10},{4,11},{4,13},{5,9},{5,10},{5,12},{6,8},{6,9},{6,11}}; for(auto[a,b]:edges){rows.push_back((1<<a)|(1<<b));target|=1ULL<<(rows.size()-1);}sort(rows.begin(),rows.end());
 for(int s=0;s<128;s++){int t=0;for(int l=0;l<7;l++){bool ok=true;for(auto[p,line]:edges)if(line==7+l&&(s>>p&1))ok=false;if(ok)t|=1<<l;}int closure=0;for(int p=0;p<7;p++){bool ok=true;for(auto[point,l]:edges)if(point==p&&(t>>(l-7)&1))ok=false;if(ok)closure|=1<<p;}if(closure==s)rows.push_back(s|(t<<7));}
 sort(rows.begin()+edges.size(),rows.end()); if(rows.size()!=55){cerr<<"FAULT row count"<<endl;return 2;}for(size_t r=0;r<rows.size();r++)for(int i=0;i<V;i++)if(rows[r]>>i&1)inputs[i]|=1ULL<<r;
 auto start=chrono::steady_clock::now();long long trial=0;int global=100000;vector<Circuit>archive;array<int,MAX>bestDef;bestDef.fill(-1);
 for(int run=0;;run++){Circuit c=seed(),local=c;if(!elastic&&rng()%4==0)for(int i=0;i<N;i++)c[i]={int(rng()%2),int(rng()%(V+i)),int(rng()%(V+i))};if(!archive.empty()&&rng()%2)c=archive[rng()%archive.size()];int s=score(c),loc=s;local=c;if(s<global){global=s;show(c,s,trial);}for(int iter=0;iter<12000;iter++,trial++){if(trial%1000==0&&(stopFlag||chrono::duration<double>(chrono::steady_clock::now()-start).count()>secs)){cout<<"done "<<trial<<" best "<<global<<endl;return 0;}int temp=elastic?((iter%2000<1000)?16:(iter%2000<1500?48:128)):((iter%400<250)?0:(iter%400<350?8:32));s=coordinate(c,rng()%N,temp);if(iter%100==0){s=resubstitute(c);if(elastic)s=pivotalStars(c);}if(elastic){collapse(c);s=score(c);}if(elastic&&s>=8192){cerr<<"FAULT lost correctness"<<endl;return 2;}if(iter%10==0){for(int j=0;j<20;j++)reorder(c);if(score(c)!=s){cerr<<"FAULT reorder"<<endl;return 2;}}if(s<loc){loc=s;local=c;}if(s<global){global=s;show(c,s,trial);}if(elastic){int co=cost(c),de=deficiency(c);if(co<=27&&de>0&&de>bestDef[co]){bestDef[co]=de;cout<<"nonlinear cost "<<co<<" missing "<<de<<" trial "<<trial<<" gates [";for(auto g:c)cout<<"("<<g.op<<","<<g.a<<","<<g.b<<"),";cout<<"]"<<endl;}}if((elastic&&cost(c)<=24)||(!elastic&&s==0)){witness(c);return 0;}if(((!elastic&&s<=global)||(elastic&&deficiency(c)>0&&cost(c)<=27))&&rng()%100==0){if(archive.size()<32)archive.push_back(c);else archive[rng()%archive.size()]=c;}if(!elastic&&iter%400==399){c=local;s=loc;}}}
}
